package org.opentollgate.android

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import org.opentollgate.android.model.ConsumeEventView
import org.opentollgate.android.model.DetectedView
import org.opentollgate.android.model.PaidView
import org.opentollgate.android.model.UiState
// Generated by `just bindings` (uniffi-bindgen). Package = uniffi.<crate>.
import uniffi.tollgate_mobile.TollgateMobileNode

/**
 * Bridges the Compose UI to the native [TollgateMobileNode]. The node owns its
 * own tokio runtime + persisted identity (under filesDir), so all calls here are
 * synchronous FFI calls dispatched off the main thread via [viewModelScope].
 *
 * PENDING (ARCHITECTURE.md §6): the full SPA-mirror UI (Cashu mint/balance,
 * Lightning, QR scan, i18n) is built once the source-of-truth decision lands.
 * The detect/pay/consume plumbing below is already wired end to end.
 */
class TollgateViewModel(app: Application) : AndroidViewModel(app) {
    private val node: TollgateMobileNode = TollgateMobileNode(app.filesDir.absolutePath)

    private val _state = MutableStateFlow(UiState(ourPubkey = node.pubkeyHex()))
    val state: StateFlow<UiState> = _state

    fun onHostChange(host: String) = _state.update { it.copy(baseHost = host) }
    fun onMintChange(mint: String) = _state.update { it.copy(mintUrl = mint) }

    fun onDetect() = viewModelScope.launch(Dispatchers.IO) {
        _state.update { it.copy(error = null) }
        runCatching { node.detect(state.value.baseHost) }
            .onSuccess { d ->
                _state.update {
                    it.copy(
                        detected = DetectedView(d.pubkeyHex, d.unit, d.version, d.price?.perUnit, d.price?.perSecond),
                        online = true,
                    )
                }
            }
            .onFailure { e -> _state.update { it.copy(error = e.message ?: "detect failed", online = false) } }
    }

    fun onPay(amountSat: Long = 21) = viewModelScope.launch(Dispatchers.IO) {
        val s = state.value
        runCatching { node.pay(s.baseHost, s.mintUrl, amountSat.toULong()) }
            .onSuccess { p ->
                _state.update { it.copy(paid = PaidView(p.peerPubkeyHex, p.accepted, p.price?.perUnit)) }
                if (p.accepted) startConsume()
            }
            .onFailure { e -> _state.update { it.copy(error = e.message ?: "pay failed") } }
    }

    private fun startConsume() {
        val s = state.value
        node.startConsume(
            base = s.baseHost,
            mint = s.mintUrl,
            amountSat = 21u,
            topupSat = 5u,
            intervalMs = 5000u,
            maxPolls = null,
        )
        viewModelScope.launch(Dispatchers.IO) {
            while (true) {
                val ev = node.pollEvent(5000u) ?: break
                _state.update {
                    it.copy(
                        latest = ConsumeEventView(
                            poll = ev.poll,
                            remainingScaled = ev.remainingScaled,
                            delivered = ev.report?.delivered,
                            cutOff = ev.cutOff,
                            toppedUp = ev.toppedUp,
                        )
                    )
                }
            }
        }
    }

    fun onStop() {
        runCatching { node.stopConsume() }
    }
}
